#include <chrono>
#include <cstdio>
#include <vector>

double suma_serial(const std::vector<double>& v) {
    double s = 0.0;
    for (double x : v) s += x;  // una dependencia encadenada
    return s;
}

double suma_cuatro(const std::vector<double>& v) {
    double a = 0.0, b = 0.0, c = 0.0, d = 0.0;
    const std::size_t n = v.size();
    std::size_t i = 0;
    for (; i + 4 <= n; i += 4) {
        a += v[i];
        b += v[i + 1];
        c += v[i + 2];
        d += v[i + 3];
    }
    for (; i < n; ++i) a += v[i];
    return a + b + c + d;
}

int main() {
    std::vector<double> v(50'000'000, 1.0);

    const auto t0 = std::chrono::steady_clock::now();
    const double r1 = suma_serial(v);
    const auto t1 = std::chrono::steady_clock::now();
    const double r2 = suma_cuatro(v);
    const auto t2 = std::chrono::steady_clock::now();

    auto ms = [](auto x, auto y) {
        return std::chrono::duration<double, std::milli>(y - x).count();
    };
    std::printf("serial %.2f ms -> %.0f\n", ms(t0, t1), r1);
    std::printf("cuatro %.2f ms -> %.0f\n", ms(t1, t2), r2);
    return 0;
}

#include <algorithm>
#include <chrono>
#include <cstdio>
#include <vector>

int main() {
    constexpr int n = 2048;
    std::vector<double> m(static_cast<std::size_t>(n) * n, 1.0);

    double mejor_fila = 1e9, mejor_columna = 1e9;
    double suma_fila = 0.0, suma_columna = 0.0;

    for (int repeticion = 0; repeticion < 5; ++repeticion) {
        auto t0 = std::chrono::steady_clock::now();
        double s = 0.0;
        for (int r = 0; r < n; ++r)
            for (int c = 0; c < n; ++c) s += m[static_cast<std::size_t>(r) * n + c];
        auto t1 = std::chrono::steady_clock::now();
        suma_fila = s;
        mejor_fila = std::min(mejor_fila, std::chrono::duration<double, std::milli>(t1 - t0).count());

        t0 = std::chrono::steady_clock::now();
        s = 0.0;
        for (int c = 0; c < n; ++c)
            for (int r = 0; r < n; ++r) s += m[static_cast<std::size_t>(r) * n + c];
        t1 = std::chrono::steady_clock::now();
        suma_columna = s;
        mejor_columna = std::min(mejor_columna, std::chrono::duration<double, std::milli>(t1 - t0).count());
    }

    std::printf("por fila    = %.0f  (%.2f ms)\n", suma_fila, mejor_fila);
    std::printf("por columna = %.0f  (%.2f ms)\n", suma_columna, mejor_columna);
    std::printf("factor      = %.1fx\n", mejor_columna / mejor_fila);
    return 0;
}

