#include <chrono>
#include <cstdio>
#include <numeric>
#include <vector>

double ms(std::chrono::steady_clock::time_point a, std::chrono::steady_clock::time_point b) {
    return std::chrono::duration<double, std::milli>(b - a).count();
}

int main() {
    std::vector<double> v(20'000'000, 1.0);

    const auto t0 = std::chrono::steady_clock::now();
    double s1 = 0.0;
    for (std::size_t i = 0; i < v.size(); ++i) s1 += v[i];
    const auto t1 = std::chrono::steady_clock::now();

    double s2 = 0.0;
    for (double valor : v) s2 += valor;
    const auto t2 = std::chrono::steady_clock::now();

    const double s3 = std::accumulate(v.begin(), v.end(), 0.0);
    const auto t3 = std::chrono::steady_clock::now();

    std::printf("indice     %6.2f ms  suma=%.0f\n", ms(t0, t1), s1);
    std::printf("range-for  %6.2f ms  suma=%.0f\n", ms(t1, t2), s2);
    std::printf("accumulate %6.2f ms  suma=%.0f\n", ms(t2, t3), s3);
    return 0;
}

#include <chrono>
#include <cstdio>
#include <vector>

int main() {
    constexpr int n = 1024;
    std::vector<double> m(static_cast<std::size_t>(n) * n, 1.0);
    std::vector<double> por_columna(n, 0.0);

    auto t0 = std::chrono::steady_clock::now();
    std::vector<double> a(n, 0.0);
    for (int c = 0; c < n; ++c)
        for (int r = 0; r < n; ++r) a[c] += m[static_cast<std::size_t>(r) * n + c];
    auto t1 = std::chrono::steady_clock::now();

    for (int r = 0; r < n; ++r) {
        const double* fila = &m[static_cast<std::size_t>(r) * n];
        for (int c = 0; c < n; ++c) por_columna[c] += fila[c];
    }
    auto t2 = std::chrono::steady_clock::now();

    const double ms_a = std::chrono::duration<double, std::milli>(t1 - t0).count();
    const double ms_b = std::chrono::duration<double, std::milli>(t2 - t1).count();
    std::printf("por columnas %6.2f ms  suma=%.0f\n", ms_a, a[0]);
    std::printf("una pasada   %6.2f ms  suma=%.0f\n", ms_b, por_columna[0]);
    return 0;
}

